public class Main {
    static final int MOD = 998244353;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String S = sc.next();
        int K = sc.nextInt();
        sc.close();

        int n = S.length();
        List<Integer> onesPos = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (S.charAt(i) == '1') onesPos.add(i);
        }

        int m = onesPos.size();
        long[][] dp = new long[m + 1][K + 1];
        dp[0][0] = 1;

        int zerosBefore = 0;
        for (int i = 0; i < m; i++) {
            int pos = onesPos.get(i);
            int zerosHere = pos - i; // zeros before this 1
            int canMove = zerosHere - zerosBefore;
            zerosBefore = zerosHere;

            for (int used = 0; used <= K; used++) {
                if (dp[i][used] == 0) continue;
                for (int move = 0; move <= canMove && used + move <= K; move++) {
                    dp[i + 1][used + move] = (dp[i + 1][used + move] + dp[i][used]) % MOD;
                }
            }
        }

        long ans = 0;
        for (int used = 0; used <= K; used++) {
            ans = (ans + dp[m][used]) % MOD;
        }
        System.out.println(ans);
    }
