public class Main {
    static final long MOD = 998244353L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String S = fs.next();
        long K = fs.nextLong();

        int n = S.length();
        int zeros = 0;
        for (int i = 0; i < n; i++) if (S.charAt(i) == '0') zeros++;
        int ones = n - zeros;

        // If all characters are same, no change is possible.
        if (zeros == 0 || ones == 0) {
            System.out.println(1);
            return;
        }

        // Let inv(S) = number of pairs (i<j, S[i]='1', S[j]='0').
        // One operation decreases inv by exactly 1.
        // Any binary string with same counts and inversion count in
        // [inv(S)-K, inv(S)] is reachable, and for every inversion count
        // there exists at least one such string.
        //
        // Therefore answer = number of distinct possible inversion counts
        // = min(K, inv(S)) + 1.

        long inv = 0;
        long onesSeen = 0;
        for (int i = 0; i < n; i++) {
            char c = S.charAt(i);
            if (c == '1') onesSeen++;
            else inv += onesSeen;
        }

        long ans = Math.min(K, inv) + 1;
        ans %= MOD;
        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

