                    // actually compute properly:
                    // number of zeros before this one = j
                    // if ones[i] > zeros[j], then all j zeros are before it, plus maybe more
                    // better: swaps needed = max(0, ones[i] - j)
                }
                int need = (ones[i] > j) ? (ones[i] - j) : 0;
                if (need <= k)
                    dp[i+1][j] = (dp[i+1][j] + dp[i][j]) % MOD;
            }
            // place a 0 next
