                int need = 0;
                if (i < oc && zeros[j] > ones[i]) {
                    // zeros[j] is after ones[i], need zeros[j] - i swaps? Actually:
                    // This 0 will be placed before remaining ones, so no extra swaps counted now.
                }
                // Swaps needed to bring this 0 before all remaining ones?
                // Actually easier: count swaps as inversions already done.
                int swaps_needed = 0;
                if (i > 0) {
                    // current zero at zeros[j], ones before it in original? 
                }
                // Simpler method: precompute cost.
                dp[i][j+1] = (dp[i][j+1] + dp[i][j]) % MOD;
            }
        }
    }

    // This naive DP doesn't track swaps correctly.
    // We'll switch to known solution: count inversions and DP over cost.

    // Reset
    memset(dp, 0, sizeof(dp));
    int cost[3005][3005] = {0};
    for (int i = 0; i < oc; i++) {
        for (int j = 0; j < zc; j++) {
            if (ones[i] < zeros[j]) cost[i+1][j+1] = 0;
            else cost[i+1][j+1] = ones[i] - j;
        }
    }

    dp[0][0] = 1;
    for (int i = 0; i <= oc; i++) {
        for (int j = 0; j <= zc; j++) {
            if (dp[i][j] == 0) continue;
            if (i < oc) {
                int c = (j < zc && ones[i] > zeros[j]) ? ones[i] - j : 0;
                if (c <= k)
                    dp[i+1][j] = (dp[i+1][j] + dp[i][j]) % MOD;
            }
            if (j < zc) {
                int c = (i < oc && zeros[j] > ones[i]) ? zeros[j] - i : 0;
                if (c <= k)
                    dp[i][j+1] = (dp[i][j+1] + dp[i][j]) % MOD;
            }
        }
    }

    int ans = 0;
    for (int i = 0; i <= k; i++) {
        ans = (ans + dp[oc][zc]) % MOD;
    }
    // Actually dp[oc][zc] already includes all ways with cost <= k? No, we need sum over costs.
    // Let's rebuild properly.

    // Reset
    memset(dp, 0, sizeof(dp));
    dp[0][0] = 1;
    for (int i = 0; i <= oc; i++) {
        for (int j = 0; j <= zc; j++) {
            if (dp[i][j] == 0) continue;
            if (i < oc) {
                int c = 0;
                if (j < zc) {
                    // ones[i] passes zeros[0..j-1] that are after it
                    int pass = 0;
                    for (int t = 0; t < j; t++) {
                        if (zeros[t] > ones[i]) pass++;
                    }
                    c = pass;
                }
                // simpler: c = max(0, ones[i] - j)
                c = (ones[i] > j) ? ones[i] - j : 0;
                if (c <= k)
                    dp[i+1][j] = (dp[i+1][j] + dp[i][j]) % MOD;
            }
            if (j < zc) {
                int c = 0;
                if (i < oc) {
                    int pass = 0;
                    for (int t = 0; t < i; t++) {
                        if (ones[t] > zeros[j]) pass++;
                    }
                    c = pass;
                }
                c = (zeros[j] > i) ? zeros[j] - i : 0;
                if (c <= k)
                    dp[i][j+1] = (dp[i][j+1] + dp[i][j]) % MOD;
            }
        }
    }

    printf("%d\n", dp[oc][zc] % MOD);
    return 0;
}

