#define MOD 998244353LL

static long long mod_pow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = (r * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return r;
}

int main(void) {
    int K;
    char S[200005];

    if (scanf("%d", &K) != 1) return 0;
    if (scanf("%s", S) != 1) return 0;

    int n = (int)strlen(S);

    int zeros = 0, ones = 0;
    for (int i = 0; i < n; i++) {
        if (S[i] == '0') zeros++;
        else ones++;
    }

    /* 
       Any operation swaps a chosen '1' left across at least one '0'.
       Therefore the relative order among all 0s and among all 1s never changes.
       So every reachable string is determined only by the positions of 1s.

       Let inv(S) = number of pairs (i<j, S[i]='0', S[j]='1').
       One operation decreases inv by exactly 1..something, and by choosing adjacent 01,
       we can decrease by exactly 1. Hence strings reachable in <=K operations are exactly
       those with inversion count in [max(0, inv(S)-K), inv(S)].

       Number of binary strings with z zeros and o ones and exactly t inversions
       equals coefficient of q^t in Gaussian binomial [z+o choose o]_q.
       So answer = sum of coefficients from L..R where R=inv(S), L=max(0,R-K).

       We compute DP for inversion counts:
       dp after processing j ones among all zeros:
       adding one more 1 can contribute 0..zeros inversions.
       Complexity O(ones * zeros * min(K,inv)).
    */

    long long inv = 0;
    int seen0 = 0;
    for (int i = 0; i < n; i++) {
        if (S[i] == '0') seen0++;
        else inv += seen0;
    }

    long long Lll = inv - K;
    if (Lll < 0) Lll = 0;
    int R = (int)inv;
    int L = (int)Lll;

    int maxNeed = R;
    long long *dp = (long long *)calloc((size_t)maxNeed + 1, sizeof(long long));
    long long *ndp = (long long *)calloc((size_t)maxNeed + 1, sizeof(long long));
    long long *pref = (long long *)calloc((size_t)maxNeed + 1, sizeof(long long));

    if (!dp || !ndp || !pref) return 0;

    dp[0] = 1;

    for (int j = 1; j <= ones; j++) {
        pref[0] = dp[0];
        for (int s = 1; s <= maxNeed; s++) {
            pref[s] = pref[s - 1] + dp[s];
            if (pref[s] >= MOD) pref[s] -= MOD;
        }

        for (int s = 0; s <= maxNeed; s++) {
            long long val = pref[s];
            if (s - zeros - 1 >= 0) {
                val -= pref[s - zeros - 1];
                if (val < 0) val += MOD;
            }
            ndp[s] = val;
        }

        long long *tmp = dp;
        dp = ndp;
        ndp = tmp;
    }

    long long ans = 0;
    for (int t = L; t <= R; t++) {
        ans += dp[t];
        if (ans >= MOD) ans -= MOD;
    }

    printf("%lld\n", ans % MOD);

    free(dp);
    free(ndp);
    free(pref);
    return 0;
}

