int main(){
    string S;
    int K;
    cin >> S >> K;

    set<string> reachable;
    queue<pair<string,int>> q;
    q.push({S, 0});
    reachable.insert(S);

    while(!q.empty()){
        auto [cur, ops] = q.front(); q.pop();
        if(ops >= K) continue;
        int n = cur.size();
        // Find all '1's and all '0's, move a '1' to just left of a '0'
        for(int i = 0; i < n; i++){
            if(cur[i] == '1'){
                for(int j = 0; j < n; j++){
                    if(cur[j] == '0' && j != i){
                        // insert cur[i]='1' immediately left of position j
                        string next = cur;
                        next.erase(i, 1);
                        int ins = (i < j) ? j-1 : j;
                        next.insert(ins, "1");
                        if(reachable.find(next) == reachable.end()){
                            reachable.insert(next);
                            q.push({next, ops+1});
                        }
                    }
                }
            }
        }
    }

    cout << reachable.size() % MOD << endl;
    return 0;
}

