int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long K;
    string S;
    cin >> N >> K >> S;

    // Count inversions: number of pairs (i<j, S[i]='1', S[j]='0')
    long long zeros_seen = 0;
    long long inv = 0;
    for (int i = N - 1; i >= 0; --i) {
        if (S[i] == '0') zeros_seen++;
        else inv += zeros_seen;
    }

    long long cnt0 = 0, cnt1 = 0;
    for (char c : S) {
        if (c == '0') cnt0++;
        else cnt1++;
    }

    // Maximum possible inversions among strings with same counts
    long long maxInv = cnt0 * cnt1;

    // One operation changes inversion count by exactly +1 or -1:
    // moving 1 left across some zeros increases by 1,
    // or moving 0 left across some ones decreases by 1.
    // Therefore all strings with inversion count in
    // [max(0, inv-K), min(maxInv, inv+K)] are reachable,
    // and for fixed counts of 0/1, each inversion count determines
    // at least one distinct string, so the number of distinct reachable
    // strings equals the number of reachable inversion counts.
    long long L = max(0LL, inv - K);
    long long R = min(maxInv, inv + K);

    cout << (R - L + 1) % MOD << '\n';
    return 0;
}

import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    S = input_data[0]
    K = int(input_data[1])
    MOD = 998244353

    visited = {S: 0}
    queue = deque([S])

    while queue:
        curr = queue.popleft()
        steps = visited[curr]
        if steps >= K:
            continue
        n = len(curr)
        s = list(curr)
        for j in range(n):
            if s[j] == '0':
                for i in range(j):
                    if s[i] == '1':
                        # Move s[i] to position j-1 (immediately left of j)
                        new_s = s[:i] + s[i+1:j] + ['1', '0'] + s[j+1:]
                        new_str = ''.join(new_s)
                        if new_str not in visited:
                            visited[new_str] = steps + 1
                            queue.append(new_str)

    print(len(visited) % MOD)

